--region private
function MidFestivalBtnShopBehavior:InitData()
    self._IsActive = true --self._activityMidFestivalComponent:IsActive()
    local homeDojo = self._activityMidFestivalComponent:GetHomeDojo()
    local info = homeDojo.entranceConf[self.config.index]
    self.config.id = info.id
    self.config.vo = ActivityMidFestivalMgr:LoadMainEntryVoById(self.config.id)
end

function MidFestivalBtnShopBehavior:RefreshUI()
    if not string.isEmpty(self.config.vo.name) then
        CfUtils.FillText(self.Text, self.config.vo.name)
    end
    if not string.isEmpty(self.config.vo.unlockPicture) then
        CfUtils.FillImage(self.ImgBg, self.config.vo.unlockPicture)
    end
    
    local haveRedPoint = self._activityMidFestivalComponent:GetHomeDojo():GetAchievementTaskTips() == 0
    CfUtils.SetActive(self.redPoint, haveRedPoint)
    
    local serverTime = GameUtils.GetServerTime()
    self._remainTime = self._activityMidFestivalComponent:GetHomeDojo().mallRemainTime - serverTime
    if not self._IsActive or self._remainTime <= 0 then
        local allChildGrayGraphics = self.controller.gameObject:EnsureComponent(typeof(UIAllChildGrayGraphics))
        if allChildGrayGraphics then
            allChildGrayGraphics:MarkGray(true)
        end
        CfUtils.FillText(self.TextTime, localize("已关闭"))
        return
    end

    self:RemoveTimer()
    if self._remainTime > 0 then
        self._timer = CDTimerModule.GetInstance():AddCD(1, function(count, id, countElapsed)
            if self._remainTime <= 0 then
                local allChildGrayGraphics = self.controller.gameObject:EnsureComponent(typeof(UIAllChildGrayGraphics))
                allChildGrayGraphics:MarkGray(true)
                CfUtils.FillText(self.TextTime, localize("已关闭"))
                self:RemoveTimer()
                return
            end
            CfUtils.FillText(self.TextTime, CfUtils.GetTimeHMS(self._remainTime))
            self._remainTime = self._remainTime - countElapsed
        end, self._remainTime, true, true)
    end
end
--endregion private

function MidFestivalBtnShopBehavior:RemoveTimer()
    if not isNull(self._timer) then
        CDTimerModule.GetInstance():RemoveCD(self._timer)
        self._timer = nil
    end
end

